static void aicfb_reset(struct aicfb_info *fbi) {
  struct aicfb_layer_data layer = {0};
  struct platform_driver *de = fbi->de;
  struct aic_panel *panel = fbi->panel;
  struct panel_desc *desc = fbi->desc;

  aicfb_get_panel_info(fbi);
  aicfb_fb_info_setup(fbi);
  aicfb_enable_panel(fbi, AICFB_OFF);

  layer.layer_id = AICFB_LAYER_TYPE_UI;
  layer.rect_id = 0;
  de->de_funcs->get_layer_config(&layer);

  layer.enable = 0;
  de->de_funcs->update_layer_config(&layer);
  aicfb_enable_clk(fbi, AICFB_OFF);

  aic_delay_ms(20);

  aicfb_enable_clk(fbi, AICFB_ON);

  layer.enable = 1;
  layer.rect_id = 0;

  layer.buf.size.width =
      desc ? desc->timings->hactive : panel->timings->hactive;
  layer.buf.size.height =
      desc ? desc->timings->vactive : panel->timings->vactive;

  layer.buf.stride[0] = fbi->stride;
  de->de_funcs->update_layer_config(&layer);
  aicfb_enable_panel(fbi, AICFB_ON);
}

static int handle_dbi_data(struct aic_panel *panel, struct panel_desc *desc,
                           struct panel_dbi *dbi, u32 *cmd_offset) {
  struct panel_dbi_commands *target =
      desc ? &desc->dbi->commands : &panel->dbi->commands;

  if (!target->buf) {
    target->buf = kmm_zalloc(target->len);
    if (!target->buf) {
      pr_err("Malloc dbi buf failed!\n");
      return -1;
    }
  }

  const u32 total = dbi->commands.len + *cmd_offset;

  if (total < target->len) {
    memcpy((u8 *)target->buf + *cmd_offset, dbi->commands.buf,
           dbi->commands.len);

    *cmd_offset += dbi->commands.len;
  } else if (total == target->len) {
    memcpy((u8 *)target->buf + *cmd_offset, dbi->commands.buf,
           dbi->commands.len);

    *cmd_offset = 0;
  } else {
    pr_err("Commands len is too long!\n");
    *cmd_offset = 0;
    return -1;
  }

  return 0;
}

